"""EtherCAT terminal PV and request-access generation."""

from __future__ import annotations

import re
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass
from dataclasses import field as dataclass_field
from enum import IntEnum, IntFlag
from pathlib import Path
from typing import TextIO

from . import parser
from .record import (MAX_PV_NAME_LENGTH, EnumRecordPackage, EPICSRecord,
                     RecordPackage, get_record_pv_length)

ADS_ETHERCAT_MASTER_AMS_PORT = 0xFFFF
ADS_ECAT_SLAVE_STATE_INDEX_GROUP = 0x0009
ADS_ECAT_SLAVE_PORT_BASE = 1000
ADS_UINT16_DATA_TYPE = 18
ADS_UINT16_SIZE_BYTES = 2
ASYN_ADDRESS = 0
ASYN_TIMEOUT_SECONDS = 1
DEFAULT_ECAT_STATE_SCAN_SECONDS = 2
CALC_INPUT = "A"
EPICS_RECORD_ENABLED = 0
EPICS_RECORD_DISABLED = 1
LINK_STATE_OK_RAW_VALUE = 0


class EtherCATDeviceState(IntEnum):
    """Raw Beckhoff EtherCAT device-state codes."""

    INIT = 0x01
    PREOP = 0x02
    BOOTSTRAP = 0x03
    SAFEOP = 0x04
    OP = 0x08


class EtherCATLinkFlag(IntFlag):
    """Individual link-status flags in the EtherCAT state word's high byte."""

    NOT_PRESENT = 0x01
    LINK_WITHOUT_COMM = 0x02
    MISSING_LINK = 0x04
    ADDITIONAL_LINK = 0x08
    PORT_A = 0x10
    PORT_B = 0x20
    PORT_C = 0x40
    PORT_D = 0x80


DEVICE_STATE_MASK = 0x0F
LINK_STATE_SHIFT_BITS = 8
LINK_STATE_BYTE_MASK = 0xFF
UNKNOWN_DEVICE_STATE_ENUM_INDEX = 0x0F
OK_LINK_STATE_ENUM_INDEX = 0
MULTIPLE_LINK_FLAGS_ENUM_INDEX = len(EtherCATLinkFlag) + 1
_DEVICE_STATE_ENUM_STATES = tuple(
    (state.name, index) for index, state in enumerate(EtherCATDeviceState)
)
_DEVICE_STATE_OP_ENUM_INDEX = next(
    index
    for index, state in enumerate(EtherCATDeviceState)
    if state is EtherCATDeviceState.OP
)
_DEVICE_STATE_REQUEST_STATES = tuple(
    (state.name, int(state)) for state in EtherCATDeviceState
)
_LINK_FLAG_ENUM_STATES = tuple(
    (flag.name, flag, index)
    for index, flag in enumerate(EtherCATLinkFlag, start=OK_LINK_STATE_ENUM_INDEX + 1)
)
_LINK_ENUM_STATES = (
    ("OK", OK_LINK_STATE_ENUM_INDEX),
    *((name, index) for name, _flag, index in _LINK_FLAG_ENUM_STATES),
    ("MULTIPLE_FLAGS", MULTIPLE_LINK_FLAGS_ENUM_INDEX),
)
DEVICE_STATE_CODE_CALC_EXPRESSION = f"{CALC_INPUT}&{DEVICE_STATE_MASK}"
LINK_STATE_CODE_CALC_EXPRESSION = (
    f"({CALC_INPUT}>>{LINK_STATE_SHIFT_BITS})&{LINK_STATE_BYTE_MASK}"
)


def _build_device_state_enum_calc() -> str:
    """Build a CALC expression mapping raw EtherCAT codes to mbbi enum indexes."""
    raw_to_enum = (
        f"{CALC_INPUT}=={int(state)}?{index}"
        for index, state in enumerate(EtherCATDeviceState)
    )
    return ":".join((*raw_to_enum, str(UNKNOWN_DEVICE_STATE_ENUM_INDEX)))


def _build_link_state_enum_calc() -> str:
    """Build a CALC expression mapping individual link flags to enum indexes."""
    raw_to_enum = [
        f"{CALC_INPUT}=={LINK_STATE_OK_RAW_VALUE}?{OK_LINK_STATE_ENUM_INDEX}"
    ]
    raw_to_enum.extend(
        f"{CALC_INPUT}=={int(flag)}?{index}"
        for _name, flag, index in _LINK_FLAG_ENUM_STATES
    )
    return ":".join((*raw_to_enum, str(MULTIPLE_LINK_FLAGS_ENUM_INDEX)))


DEVICE_STATE_ENUM_CALC_EXPRESSION = _build_device_state_enum_calc()
LINK_STATE_ENUM_CALC_EXPRESSION = _build_link_state_enum_calc()


def _enum_severity_fields(
    states: tuple[tuple[str, int], ...],
    no_alarm_value: int,
) -> dict[str, str]:
    """Return per-state severities, with one normal value and all others major."""
    return {
        f"{string_field[:2]}SV": (
            "NO_ALARM" if value == no_alarm_value else "MAJOR"
        )
        for (_, value), (_, string_field) in zip(
            states, EnumRecordPackage.mbb_fields
        )
    }


_ACCESS_LINE = re.compile(
    r'^\s*epicsEnvSet\("ECAT_(?P<field>ASG|DISP|DISA|DISV)_'
    r'(?P<port>\d+)_(?P<name>[A-Za-z0-9_]+)"\s*,\s*"'
    r'(?P<value>[^"]+)"\)\s*(?:#.*)?$'
)
_ACCESS_DEVICE_SECTION = re.compile(
    r"^\s*#\s*Port\s+(?P<port>\d+):\s*(?P<name>.+?)\s*$"
)
_PV_COMPONENT = re.compile(r"[^A-Za-z0-9_.-]")


@dataclass(frozen=True, order=True)
class EtherCATTerminal:
    """One terminal's fixed ADS slave address and stable project name."""

    port: int
    name: str
    xti_id: str | None = dataclass_field(default=None, compare=False)

    @property
    def pv_component(self) -> str:
        return _PV_COMPONENT.sub("_", self.name)

    @property
    def pv_base(self) -> str:
        return f"$(PREFIX)ECAT:{self.port}"

    @property
    def access_component(self) -> str:
        return re.sub(r"[^A-Za-z0-9_]", "_", self.pv_component)


@dataclass(frozen=True)
class EtherCATAccess:
    """Write access permissions for the EtherCAT state of one terminal."""

    terminal: EtherCATTerminal
    caput_allowed: bool
    internal_processing_allowed: bool


def _fixed_ethercat_port(
    name: str,
    sections: list[parser.EtherCAT],
) -> int | None:
    """Return the explicitly configured fixed ADS port, if any."""
    fixed_port = None
    for section in sections:
        fixed = section.attributes.get("EtherCatAddrFixed", "false").strip().lower()
        if fixed not in ("true", "false"):
            raise ValueError(f"Invalid EtherCatAddrFixed value {fixed!r} for {name}")
        if fixed == "false":
            continue

        raw_port = section.attributes.get("EtherCatAddr")
        if raw_port is None:
            raise ValueError(f"{name} has EtherCatAddrFixed=true without EtherCatAddr")
        try:
            if raw_port.lower().startswith("#x"):
                port = int(raw_port[2:], 16)
            elif raw_port.lower().startswith("0x"):
                port = int(raw_port, 16)
            else:
                port = int(raw_port, 10)
        except ValueError as ex:
            raise ValueError(f"Invalid EtherCatAddr {raw_port!r} for {name}") from ex

        if not ADS_ECAT_SLAVE_PORT_BASE < port <= 0xFFFF:
            raise ValueError(f"EtherCatAddr for {name} is out of range: {port}")
        if fixed_port is not None and fixed_port != port:
            raise ValueError(f"{name} has conflicting fixed EtherCAT ports")
        fixed_port = port

    return fixed_port


def _assign_ethercat_ports(
    terminal_ports: list[tuple[str, int | None]],
) -> list[EtherCATTerminal]:
    """Apply fixed ports first, then allocate free ports in tree order."""
    fixed_owners: dict[int, str] = {}
    for name, fixed_port in terminal_ports:
        if fixed_port is None:
            continue
        previous_name = fixed_owners.get(fixed_port)
        if previous_name is not None:
            raise ValueError(
                f"Duplicate EtherCAT ADS port {fixed_port}: "
                f"{previous_name!r} and {name!r}"
            )
        fixed_owners[fixed_port] = name

    reserved_ports = set(fixed_owners)
    assigned_ports = set(reserved_ports)
    highest_port = ADS_ECAT_SLAVE_PORT_BASE
    terminals = []
    for name, fixed_port in terminal_ports:
        if fixed_port is None:
            port = highest_port + 1
            while port in reserved_ports or port in assigned_ports:
                port += 1
        else:
            port = fixed_port

        if port > 0xFFFF:
            raise ValueError("EtherCAT slave ports exceed the ADS port range")
        terminals.append(EtherCATTerminal(port=port, name=name))
        assigned_ports.add(port)
        highest_port = max(highest_port, port)

    return terminals


def get_ethercat_terminals(project: parser.TwincatItem) -> list[EtherCATTerminal]:
    """Return state-capable boxes with fixed ADS ports in TwinCAT tree order."""
    terminal_ports = []
    terminal_ids = []
    for box in project.root.find(parser.Box):
        sections = getattr(box, "EtherCAT", ())
        if not any(
            section.attributes.get("SlaveType") is not None
            for section in sections
        ):
            continue
        if not box.name:
            raise ValueError(f"EtherCAT box is missing its name: {box!r}")

        terminal_ports.append(
            (box.name, _fixed_ethercat_port(box.name, sections))
        )
        terminal_ids.append(box.attributes.get("Id"))

    return [
        EtherCATTerminal(terminal.port, terminal.name, xti_id)
        for terminal, xti_id in zip(
            _assign_ethercat_ports(terminal_ports), terminal_ids
        )
    ]


def _terminal_alias_components(
    terminals: list[EtherCATTerminal],
    macro_substitutions: Mapping[str, str],
) -> list[str]:
    """Return unique sanitized terminal components fitting the alias PV limit."""
    if not terminals:
        return []

    fixed_record = EPICSRecord(
        "$(PREFIX)ECAT::State_RBV", "mbbi", "input"
    )
    available_length = MAX_PV_NAME_LENGTH - get_record_pv_length(
        fixed_record, macro_substitutions
    )
    if available_length < 0:
        raise ValueError(
            "The expanded PREFIX leaves no room for an EtherCAT terminal "
            f"alias component within {MAX_PV_NAME_LENGTH} characters"
        )

    components = [
        terminal.pv_component[:available_length] for terminal in terminals
    ]
    component_counts = Counter(components)
    colliding_indices = {
        index
        for index, component in enumerate(components)
        if component_counts[component] > 1
    }
    if not colliding_indices:
        return components

    id_counts = Counter(
        sanitized_id
        for terminal in terminals
        if (sanitized_id := _PV_COMPONENT.sub("_", terminal.xti_id or ""))
    )
    identified_indices = set(colliding_indices)
    while identified_indices:
        for index in identified_indices:
            terminal = terminals[index]
            sanitized_id = _PV_COMPONENT.sub("_", terminal.xti_id or "")
            if sanitized_id and id_counts[sanitized_id] == 1:
                unique_id = f"id-{sanitized_id}"
            else:
                unique_id = f"port-{terminal.port}"
            suffix = f"_{unique_id}"
            name_length = available_length - len(suffix)
            if name_length < 0:
                raise ValueError(
                    "The expanded PREFIX leaves no room for an EtherCAT "
                    f"terminal identifier within {MAX_PV_NAME_LENGTH} characters"
                )
            components[index] = terminal.pv_component[:name_length] + suffix

        updated_counts = Counter(components)
        newly_colliding = {
            index
            for index, component in enumerate(components)
            if updated_counts[component] > 1 and index not in identified_indices
        }
        if not newly_colliding:
            break
        identified_indices.update(newly_colliding)

    if len(components) != len(set(components)):
        raise ValueError(
            "Unable to generate unique EtherCAT terminal aliases within "
            f"{MAX_PV_NAME_LENGTH} characters"
        )
    return components


class EtherCATRecordPackage(RecordPackage):
    """A terminal's EtherCAT state, link, and requested-state records."""

    def __init__(self, terminal: EtherCATTerminal, alias_component: str):
        self.terminal = terminal
        self.alias_component = alias_component
        self.tcname = terminal.name
        self.pvname = terminal.pv_base
        self.aliases = []
        self.archive_settings = None
        self.config = {}
        self.long_description = None
        self.linked_to_pv = None

    @property
    def valid(self) -> bool:
        return True

    def _asyn_link(self) -> str:
        index_offset = self.terminal.port
        return (
            f"@asyn($(PORT),{ASYN_ADDRESS},{ASYN_TIMEOUT_SECONDS})"
            f"ADSPORT={ADS_ETHERCAT_MASTER_AMS_PORT}/.ADR."
            f"16#{ADS_ECAT_SLAVE_STATE_INDEX_GROUP:x},16#{index_offset:x},"
            f"{ADS_UINT16_SIZE_BYTES},{ADS_UINT16_DATA_TYPE}="
        )

    def _terminal_alias(self, suffix: str) -> str:
        return f"$(PREFIX)ECAT:{self.alias_component}:{suffix}"

    def _enum_fields(
        self,
        states: tuple[tuple[str, int], ...],
    ) -> dict[str, str | int]:
        """Return standard EPICS enum fields for named states."""
        if len(states) > len(EnumRecordPackage.mbb_fields):
            raise ValueError(
                f"EPICS enum supports at most {len(EnumRecordPackage.mbb_fields)} states"
            )
        fields: dict[str, str | int] = {}
        for (label, value), (value_field, text_field) in zip(
            states, EnumRecordPackage.mbb_fields
        ):
            fields[text_field] = label
            fields[value_field] = value
        return fields

    def _record(
        self,
        record_type: str,
        name: str,
        *,
        link: str,
        write: bool,
        dtype: str = "asynInt32",
        access_key: str | None = None,
        scan_period: str | None = None,
        process_on_init: bool = False,
        forward_link: str | None = None,
        aliases: list[str] | None = None,
    ) -> EPICSRecord:
        direction = "output" if write else "input"
        fields: dict[str, str | int] = {
            "DTYP": dtype,
            "OUT" if write else "INP": link,
            "DESC": self.terminal.name,
        }
        if write:
            if access_key is None:
                raise ValueError("A write record must have an EtherCAT access key")
            fields.update(
                {
                    "DISP": f"$(ECAT_DISP_{access_key}={EPICS_RECORD_DISABLED})",
                    "DISA": f"$(ECAT_DISA_{access_key}={EPICS_RECORD_DISABLED})",
                    "DISV": EPICS_RECORD_DISABLED,
                    "ASG": f"$(ECAT_ASG_{access_key}=NO_WRITE)",
                    **self._enum_fields(_DEVICE_STATE_REQUEST_STATES),
                }
            )
        else:
            if scan_period:
                fields["SCAN"] = scan_period
            if process_on_init:
                fields["PINI"] = "YES"
        if forward_link:
            fields["FLNK"] = forward_link
        return EPICSRecord(
            pvname=name,
            record_type=record_type,
            direction=direction,
            fields=fields,
            aliases=aliases,
        )

    def _calc_record(
        self,
        name: str,
        input_pv: str,
        expression: str,
        *,
        forward_link: str | None = None,
    ) -> EPICSRecord:
        fields = {
            "INPA": f"{input_pv} NPP NMS",
            "CALC": expression,
            "SCAN": "Passive",
            "DESC": self.terminal.name,
        }
        if forward_link:
            fields["FLNK"] = forward_link
        return EPICSRecord(
            pvname=name,
            record_type="calc",
            direction="input",
            fields=fields,
        )

    def _state_scan_period_field(self) -> str:
        """Return the shared configurable scan period field for readbacks."""
        return (
            f"$(ECAT_STATE_SCAN_SECONDS={DEFAULT_ECAT_STATE_SCAN_SECONDS}) second"
        )

    @property
    def records(self) -> list[EPICSRecord]:
        terminal = self.terminal
        base = terminal.pv_base
        description = terminal.name
        raw_state = f"{base}:StateRaw"
        state_code = f"{base}:StateCode"
        state_value = f"{base}:StateValue"
        link_code = f"{base}:LinkCode"
        link_value = f"{base}:LinkValue"

        return [
            self._record(
                "longin",
                raw_state,
                link=self._asyn_link(),
                write=False,
                scan_period=self._state_scan_period_field(),
                process_on_init=False,
                forward_link=state_code,
            ),
            self._calc_record(
                state_code,
                f"{raw_state}.VAL",
                DEVICE_STATE_CODE_CALC_EXPRESSION,
                forward_link=state_value,
            ),
            self._calc_record(
                state_value,
                f"{state_code}.VAL",
                DEVICE_STATE_ENUM_CALC_EXPRESSION,
                forward_link=f"{base}:State_RBV",
            ),
            self._calc_record(
                link_code,
                f"{raw_state}.VAL",
                LINK_STATE_CODE_CALC_EXPRESSION,
                forward_link=link_value,
            ),
            self._calc_record(
                link_value,
                f"{link_code}.VAL",
                LINK_STATE_ENUM_CALC_EXPRESSION,
                forward_link=f"{base}:Link_RBV",
            ),
            EPICSRecord(
                pvname=f"{base}:State_RBV",
                record_type="mbbi",
                direction="input",
                fields={
                    "DTYP": "Soft Channel",
                    "INP": f"{state_value} NPP NMS",
                    "DESC": description,
                    **self._enum_fields(_DEVICE_STATE_ENUM_STATES),
                    **_enum_severity_fields(
                        _DEVICE_STATE_ENUM_STATES, _DEVICE_STATE_OP_ENUM_INDEX
                    ),
                    "UNSV": "MAJOR",
                    "SCAN": "Passive",
                    "FLNK": link_code,
                },
                aliases=[self._terminal_alias("State_RBV")],
            ),
            EPICSRecord(
                pvname=f"{base}:Link_RBV",
                record_type="mbbi",
                direction="input",
                fields={
                    "DTYP": "Soft Channel",
                    "INP": f"{link_value} NPP NMS",
                    "DESC": description,
                    **self._enum_fields(_LINK_ENUM_STATES),
                    **_enum_severity_fields(
                        _LINK_ENUM_STATES, OK_LINK_STATE_ENUM_INDEX
                    ),
                    "SCAN": "Passive",
                },
                aliases=[self._terminal_alias("Link_RBV")],
            ),
            self._record(
                "mbbo",
                f"{base}:State_SP",
                link=self._asyn_link(),
                write=True,
                access_key=f"{terminal.port}_{terminal.access_component}",
                aliases=[self._terminal_alias("State_SP")],
            ),
        ]


def create_ethercat_packages(
    terminals: list[EtherCATTerminal],
    macro_substitutions: Mapping[str, str],
) -> list[EtherCATRecordPackage]:
    """Create one standard-renderable record package for each terminal."""
    components = _terminal_alias_components(terminals, macro_substitutions)
    return [
        EtherCATRecordPackage(terminal, component)
        for terminal, component in zip(terminals, components)
    ]


def render_ethercat_database(
    terminals: list[EtherCATTerminal],
    macro_substitutions: Mapping[str, str],
) -> str:
    """Render terminal packages through pytmc's standard record renderer."""
    return "\n\n".join(
        package.render().strip()
        for package in create_ethercat_packages(terminals, macro_substitutions)
    )


def render_default_access_config(terminals: list[EtherCATTerminal]) -> str:
    """Render a safe, editable IOC-shell access config with all requests denied."""
    lines = [
        "# EtherCAT state-request access policy.",
        "# Requests are disabled by default (ASG=NO_WRITE, DISP=1, DISA=DISV=1).",
        "# Uncomment all three epicsEnvSet lines to permit state requests.",
        "# This file is created once and is not overwritten by regeneration.",
        "",
    ]
    for terminal in terminals:
        lines.extend(_access_device_config_lines(terminal, {}))
    return "\n".join(lines)


def _access_device_config_lines(
    terminal: EtherCATTerminal,
    assignments: dict[str, int | str],
) -> list[str]:
    """Render one terminal's access entries, retaining configured gate values."""
    key = f"{terminal.port}_{terminal.access_component}"
    lines = [f"# Port {terminal.port}: {terminal.name}"]
    defaults = (
        ("ASG", "DEFAULT"),
        ("DISP", str(EPICS_RECORD_ENABLED)),
        ("DISA", str(EPICS_RECORD_ENABLED)),
    )
    for field, default in defaults:
        configured = assignments.get(field)
        value = default if configured is None else configured
        line = f'epicsEnvSet("ECAT_{field}_{key}", "{value}")'
        lines.append(line if configured is not None else f"# {line}")

    if "DISV" in assignments:
        lines.append(
            f'epicsEnvSet("ECAT_DISV_{key}", "{assignments["DISV"]}")'
        )
    lines.append("")
    return lines


def access_macro_substitutions(terminals: list[EtherCATTerminal]) -> str:
    """Return DB-load macros that resolve each terminal's default-deny gates."""
    macros = []
    for terminal in terminals:
        key = f"{terminal.port}_{terminal.access_component}"
        for field, default in (
            ("ASG", "NO_WRITE"),
            ("DISP", str(EPICS_RECORD_DISABLED)),
            ("DISA", str(EPICS_RECORD_DISABLED)),
        ):
            name = f"ECAT_{field}_{key}"
            macros.append(f"{name}=$({name}={default})")
    return ",".join(macros)


def generate_ethercat_files(
    project: parser.TwincatItem,
    plc_database_path: str | Path,
    macro_substitutions: Mapping[str, str],
) -> tuple[Path | None, Path | None]:
    """Generate the EtherCAT database and initialize its access config once."""
    terminals = get_ethercat_terminals(project)
    if not terminals:
        return None, None

    plc_database_path = Path(plc_database_path)
    database_path = plc_database_path.with_name(
        f"{plc_database_path.stem}_EtherCAT.db"
    )
    config_path = plc_database_path.with_name(
        f"{plc_database_path.stem}_ethercat_state_access.cmd"
    )
    database_path.write_text(
        render_ethercat_database(terminals, macro_substitutions),
        encoding="utf-8",
    )
    try:
        with config_path.open("x", encoding="utf-8") as config_file:
            config_file.write(render_default_access_config(terminals))
    except FileExistsError:
        pass
    return database_path, config_path


def read_access_config(
    path: str | Path,
) -> dict[tuple[int, str], dict[str, int | str]]:
    """Read the supported dbpf gate assignments from an IOC-shell script."""
    path = Path(path)
    assignments: dict[tuple[int, str], dict[str, int | str]] = {}
    for line_number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        stripped = line.strip()
        if stripped.startswith("#") or not stripped:
            continue
        match = _ACCESS_LINE.fullmatch(line)
        if match:
            key = (int(match["port"]), match["name"])
            field = match["field"]
            value = match["value"]
            if field == "ASG":
                if value not in ("DEFAULT", "NO_WRITE"):
                    raise ValueError(
                        f"Unsupported EtherCAT access group at {path}:{line_number}: {value}"
                    )
            elif value not in ("0", "1"):
                raise ValueError(
                    f"Unsupported EtherCAT gate value at {path}:{line_number}: {value}"
                )
            assignments.setdefault(key, {})[field] = (
                value if field == "ASG" else int(value)
            )
        elif "ECAT_" in line:
            raise ValueError(
                f"Unsupported EtherCAT access rule at {path}:{line_number}: {line}"
            )
    return assignments


def access_config_device_changes(
    terminals: list[EtherCATTerminal],
    config_path: str | Path,
) -> tuple[list[EtherCATTerminal], list[EtherCATTerminal]]:
    """Return added and removed devices compared with an access config."""
    config_path = Path(config_path)
    assignments = read_access_config(config_path)
    existing: dict[tuple[int, str], str | None] = {}
    for line in config_path.read_text(encoding="utf-8").splitlines():
        match = _ACCESS_DEVICE_SECTION.fullmatch(line)
        if match:
            port = int(match["port"])
            name = match["name"]
            component = EtherCATTerminal(port, name).access_component
            existing[(port, component)] = name

    for port, component in assignments:
        existing.setdefault((port, component), None)

    desired = {
        (terminal.port, terminal.access_component): terminal
        for terminal in terminals
    }
    added = sorted(
        terminal
        for key, terminal in desired.items()
        if key not in existing or existing[key] not in (None, terminal.name)
    )
    removed = sorted(
        EtherCATTerminal(port=port, name=name or component)
        for (port, component), name in existing.items()
        if (port, component) not in desired
        or (name is not None and desired[(port, component)].name != name)
    )
    return added, removed


def render_updated_access_config(
    terminals: list[EtherCATTerminal],
    config_path: str | Path,
) -> str:
    """Render sorted access entries while retaining assignments for known devices."""
    assignments = read_access_config(config_path)
    lines = [
        "# EtherCAT state-request access policy.",
        "# Requests are disabled by default (ASG=NO_WRITE, DISP=1, DISA=DISV=1).",
        "# Uncomment all three epicsEnvSet lines to permit state requests.",
        "# This file is created once and is not overwritten by regeneration.",
        "",
    ]
    for terminal in sorted(terminals):
        key = (terminal.port, terminal.access_component)
        lines.extend(_access_device_config_lines(terminal, assignments.get(key, {})))
    return "\n".join(lines)


def effective_access(
    terminals: list[EtherCATTerminal],
    assignments: dict[tuple[int, str], dict[str, int | str]],
) -> tuple[list[EtherCATAccess], list[tuple[int, str]]]:
    """Evaluate caput and internal request gates; missing rules are denied."""
    terminal_keys = {
        (terminal.port, terminal.access_component) for terminal in terminals
    }
    unmatched = sorted(set(assignments) - terminal_keys)
    decisions = []
    for terminal in terminals:
        values = assignments.get(
            (terminal.port, terminal.access_component), {}
        )
        disp = values.get("DISP", EPICS_RECORD_DISABLED)
        disa = values.get("DISA", EPICS_RECORD_DISABLED)
        disv = values.get("DISV", EPICS_RECORD_DISABLED)
        asg = values.get("ASG", "NO_WRITE")
        decisions.append(
            EtherCATAccess(
                terminal=terminal,
                caput_allowed=disp == EPICS_RECORD_ENABLED and asg == "DEFAULT",
                internal_processing_allowed=disa != disv,
            )
        )
    return decisions, unmatched


def print_access_report(
    terminals: list[EtherCATTerminal],
    config_path: str | Path,
    output: TextIO,
) -> None:
    """Print effective access for the project terminals and config script."""
    assignments = read_access_config(config_path)
    decisions, unmatched = effective_access(terminals, assignments)
    print("PORT  DEVICE                 CAPUT       INTERNAL", file=output)
    for decision in decisions:
        caput = "ALLOWED" if decision.caput_allowed else "DENIED"
        internal = (
            "ALLOWED" if decision.internal_processing_allowed else "DISABLED"
        )
        print(
            f"{decision.terminal.port:<5} "
            f"{decision.terminal.name:<22} {caput:<11} {internal}",
            file=output,
        )
    for port, name in unmatched:
        print(f"Unmatched access rule: port={port} device={name}", file=output)
